#!/usr/bin/env python3
"""Focused regression harness for the mod_http2 NULL-brigade guard (CU-001).

Run from a target checkout (the patched candidate or a clean target tree). It:
  1. reads the candidate modules/http2/h2_c2.c from the working tree,
  2. reads the baseline modules/http2/h2_c2.c from HEAD,
  3. extracts the *verbatim* beam_out + h2_c2_filter_out functions from each,
  4. compiles them against minimal stubs and the real checkout include/ap_mmn.h,
  5. runs:
       - baseline with bb == NULL  -> must terminate abnormally (assert/abort),
       - candidate with bb == NULL -> must return APR_SUCCESS, clear
         data_in_output_filters and never reach the beam,
       - candidate with a non-NULL brigade -> must reach the beam and return
         APR_SUCCESS (positive path unchanged).
Exit 0 only if all expectations hold.
"""
from __future__ import annotations

import os
import subprocess
import sys
import tempfile
from pathlib import Path

PREAMBLE = r'''
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "ap_mmn.h"

typedef int apr_status_t;
typedef long apr_off_t;
#define APR_SUCCESS 0
#define APR_BLOCK_READ 0
#define APR_STATUS_IS_EAGAIN(s) ((s) == 90000)
#define APLOG_MARK __FILE__, __LINE__
#define APLOG_TRACE2 0
#define AP_HAS_RESPONSE_BUCKETS 0
#define APR_BRIGADE_EMPTY(b) ((b)->first == (b)->last)
#define APR_BRIGADE_SENTINEL(b) ((void*)0)
#define APR_BRIGADE_FIRST(b) ((void*)0)
#define APR_BUCKET_NEXT(e) ((void*)0)

typedef struct conn_rec { void *conn_config; int data_in_output_filters; } conn_rec;
typedef struct h2_conn_ctx_t { const char *id; int stream_id; void *beam_out; } h2_conn_ctx_t;
typedef struct ap_filter_t { conn_rec *c; } ap_filter_t;
typedef struct apr_bucket_brigade { void *first; void *last; } apr_bucket_brigade;

#define h2_conn_ctx_get(c) ((h2_conn_ctx_t*)((c)->conn_config))
#define ap_assert(exp) do { if (!(exp)) { fprintf(stderr, "ap_assert failed: %s\n", #exp); abort(); } } while (0)

static int g_beam_calls = 0;
static void ap_log_cerror(const char *file, int line, int level,
                          apr_status_t status, conn_rec *c, const char *fmt, ...) {
    (void)file; (void)line; (void)level; (void)status; (void)c; (void)fmt;
}
static void h2_c2_abort(conn_rec *a, conn_rec *b) { (void)a; (void)b; }
static apr_status_t h2_beam_send(void *beam, conn_rec *from,
                                 apr_bucket_brigade *sender_bb, int block,
                                 apr_off_t *pwritten) {
    (void)beam; (void)from; (void)block;
    g_beam_calls++;
    /* mirrors target modules/http2/h2_bucket_beam.c: ap_assert(sender_bb) */
    ap_assert(sender_bb);
    if (pwritten) *pwritten = 0;
    if (sender_bb && APR_BRIGADE_EMPTY(sender_bb)) return APR_SUCCESS;
    return APR_SUCCESS;
}

/* ---- BEGIN verbatim extracted target functions ---- */
'''

POSTAMBLE = r'''
/* ---- END verbatim extracted target functions ---- */

int main(int argc, char **argv) {
    const char *mode = argc > 1 ? argv[1] : "null";
    h2_conn_ctx_t ctx;
    conn_rec c;
    ap_filter_t f;
