    ctx.stream_id = 1;
    ctx.beam_out = &bb;
    c.conn_config = &ctx;
    c.data_in_output_filters = 7;
    f.c = &c;

    if (strcmp(mode, "null") == 0) {
        apr_status_t rv = h2_c2_filter_out(&f, NULL);
        fprintf(stderr, "NULL rv=%d flag=%d beam=%d\n",
