        if (rv != APR_SUCCESS) return 2;
        if (c.data_in_output_filters != 0) return 3;
        if (g_beam_calls != 0) return 4;
        printf("CAND_NULL_OK\n");
        return 0;
    }
    if (strcmp(mode, "nonnull") == 0) {
        apr_status_t rv = h2_c2_filter_out(&f, &bb);
        fprintf(stderr, "NONNULL rv=%d flag=%d beam=%d\n",
                rv, c.data_in_output_filters, g_beam_calls);
        if (rv != APR_SUCCESS) return 5;
        if (g_beam_calls != 1) return 6;
        printf("CAND_NONNULL_OK\n");
        return 0;
    }
    if (strcmp(mode, "rawnull") == 0) {
        volatile apr_status_t rv = h2_c2_filter_out(&f, NULL);
        (void)rv;
        printf("UNEXPECTED_SURVIVAL\n");
        return 0;
