'''

START_MARKER = "static apr_status_t beam_out"
END_MARKER = "static int addn_headers"


def extract(source: str) -> str:
    start = source.find(START_MARKER)
    end = source.find(END_MARKER)
    if start < 0 or end < 0 or end <= start:
        raise SystemExit("could not locate function region in source")
    return source[start:end].rstrip() + "\n"


def build(cc: str, root: Path, name: str, functions: str, workdir: Path) -> Path:
    csrc = workdir / f"{name}.c"
    binary = workdir / name
    csrc.write_text(PREAMBLE + functions + POSTAMBLE, encoding="utf-8")
    cmd = [cc, "-std=gnu11", "-Wall", "-Wno-unused-function", "-Wno-unused-variable",
           "-I", str(root / "include"), "-o", str(binary), str(csrc)]
    result = subprocess.run(cmd, capture_output=True, text=True)
    if result.returncode != 0:
        raise SystemExit(f"compile {name} failed:\n{result.stdout}\n{result.stderr}")
    return binary


def run(binary: Path, mode: str) -> subprocess.CompletedProcess:
    return subprocess.run([str(binary), mode], capture_output=True, text=True)


def main() -> int:
    root = Path.cwd()
    target = root / "modules" / "http2" / "h2_c2.c"
    if not target.is_file() or not (root / "include" / "ap_mmn.h").is_file():
        print(f"not a target checkout: {root}", file=sys.stderr)
        return 10
    candidate_src = target.read_text(encoding="utf-8")
    git = subprocess.run(["git", "show", "HEAD:modules/http2/h2_c2.c"],
                         capture_output=True, text=True)
    if git.returncode != 0:
        print(f"cannot read baseline from HEAD: {git.stderr}", file=sys.stderr)
        return 11
    baseline_src = git.stdout
    if candidate_src == baseline_src:
        print("candidate source equals baseline; patch not present", file=sys.stderr)
        return 12

    cc = os.environ.get("CC", "gcc")
    failures: list[str] = []
    with tempfile.TemporaryDirectory(prefix="h2-null-guard-") as tmp:
        workdir = Path(tmp)
        base_bin = build(cc, root, "baseline", extract(baseline_src), workdir)
        cand_bin = build(cc, root, "candidate", extract(candidate_src), workdir)

        base = run(base_bin, "rawnull")
        print(f"baseline NULL: returncode={base.returncode} rc<0 means killed by signal")
        if base.returncode >= 0:
            failures.append(f"baseline NULL did not crash (rc={base.returncode}, out={base.stdout!r})")
        else:
            print(f"baseline NULL crashed as expected (signal {-base.returncode})")

        cand_null = run(cand_bin, "null")
        print(f"candidate NULL: rc={cand_null.returncode} stdout={cand_null.stdout.strip()} stderr={cand_null.stderr.strip()}")
        if cand_null.returncode != 0 or "CAND_NULL_OK" not in cand_null.stdout:
            failures.append(f"candidate NULL guard failed (rc={cand_null.returncode})")

        cand_nonnull = run(cand_bin, "nonnull")
        print(f"candidate non-NULL: rc={cand_nonnull.returncode} stdout={cand_nonnull.stdout.strip()} stderr={cand_nonnull.stderr.strip()}")
        if cand_nonnull.returncode != 0 or "CAND_NONNULL_OK" not in cand_nonnull.stdout:
            failures.append(f"candidate positive path failed (rc={cand_nonnull.returncode})")

    if failures:
        print("HARNESS FAILED:")
        for item in failures:
            print(f"  - {item}")
        return 1
    print("HARNESS PASSED: baseline NULL-brigade crashes; candidate guards and positive path unchanged")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

